--liquibase formatted sql
--changeset vstavrou:021-create-quote-tbl
--preconditions onFail:MARK_RAN
--precondition-sql-check expectedResult:0 SELECT COUNT(*) FROM information_schema.tables WHERE table_schema = 'requests' AND table_name = 'quote';
CREATE TABLE "requests"."quote"
(
    "quote_id"           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "request_id"         bigint       NOT NULL,
    "quote_state"        varchar(255) NOT NULL,
    "client_accepted_at" timestamp,
    "quote_amount"       number,
    CHECK (quote_state in ('QUOTED', 'ACCEPTED', 'REJECTED'))
);

COMMENT
ON TABLE "requests"."quote" IS 'This table will hold the quotations a service provider quotes for a request.'
COMMENT
ON COLUMN "requests"."quote"."quote_state" IS '''QUOTED'',''ACCEPTED'',''REJECTED''';

CREATE INDEX ON "requests"."quote" ("request_id");
